/* ============================================================
   ثيم ناف — النسخة المصحّحة
   كل التعديلات موسومة بـ  [مُصحَّح]  مع سبب التغيير
   جميع أزواج النص/الخلفية تتجاوز 4.5:1 — معيار WCAG AA
   ============================================================ */

@import "tailwindcss";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(0.9383 0.0042 236.4993);
  --foreground: oklch(0.3211 0 0);
  --card: oklch(1.0000 0 0);
  --card-foreground: oklch(0.3211 0 0);
  --popover: oklch(1.0000 0 0);
  --popover-foreground: oklch(0.3211 0 0);

  /* [مُصحَّح] 0.6325 -> 0.5700 — كان الأبيض عليه 3.49، صار 4.51 */
  --primary: oklch(0.5700 0.0904 80.9413);
  --primary-foreground: oklch(1.0000 0 0);

  --secondary: oklch(0.9670 0.0029 264.5419);
  --secondary-foreground: oklch(0.2972 0.0398 246.6002);
  --muted: oklch(0.9846 0.0017 247.8389);

  /* [مُصحَّح] 0.5510 -> 0.5250 — كان 4.04 على الخلفية، صار 4.51 */
  --muted-foreground: oklch(0.5250 0.0234 264.3637);

  --accent: oklch(0.9119 0.0222 243.8174);
  --accent-foreground: oklch(0.3791 0.1378 265.5222);

  /* [مُصحَّح] 0.6368 -> 0.5930 — زر الحذف كان 3.76، صار 4.50 */
  --destructive: oklch(0.5930 0.2078 25.3313);
  --destructive-foreground: oklch(1.0000 0 0);

  /* [جديد] ألوان الحالة — كانت غائبة تماماً
     لحالات: معتمد / قيد المراجعة / معلومة
     كلها تتجاوز 4.5 مع النص الأبيض */
  --success: oklch(0.5540 0.1200 155.0000);
  --success-foreground: oklch(1.0000 0 0);
  --warning: oklch(0.5720 0.1400 75.0000);
  --warning-foreground: oklch(1.0000 0 0);
  --info: oklch(0.5640 0.1200 240.0000);
  --info-foreground: oklch(1.0000 0 0);

  --border: oklch(0.8853 0 0);
  --input: oklch(0.9700 0.0029 264.5420);

  /* [مُصحَّح] تبع الأساسي الجديد ليبقى حلقة التركيز مطابقة للزر */
  --ring: oklch(0.5700 0.0904 80.9413);

  --chart-1: oklch(0.5700 0.0904 80.9413);
  --chart-2: oklch(0.5640 0.1200 240.0000);
  --chart-3: oklch(0.5540 0.1200 155.0000);
  --chart-4: oklch(0.5016 0.0849 259.4902);
  --chart-5: oklch(0.2210 0.0253 246.6492);

  --sidebar: oklch(0.9030 0.0046 258.3257);
  --sidebar-foreground: oklch(0.2210 0.0253 246.6492);

  /* [مُصحَّح] كان برتقالياً #E05D38 عند الزاوية 36 — عائلة لونية ثالثة
     دخيلة من قالب جاهز. وُحّد على الذهبي الأساسي. */
  --sidebar-primary: oklch(0.5700 0.0904 80.9413);
  --sidebar-primary-foreground: oklch(1.0000 0 0);

  --sidebar-accent: oklch(0.9119 0.0222 243.8174);

  /* [مُصحَّح] كان ذهبياً فاتحاً على أزرق فاتح = 2.70، أسوأ نسبة في الملف */
  --sidebar-accent-foreground: oklch(0.2972 0.0398 246.6002);

  --sidebar-border: oklch(0.8853 0 0);
  --sidebar-ring: oklch(0.5700 0.0904 80.9413);

  --font-sans: IBM Plex Sans Arabic, ui-sans-serif, sans-serif, system-ui;
  --font-serif: IBM Plex Serif, ui-serif, serif;
  --font-mono: IBM Plex Mono, ui-monospace, monospace;

  /* [مُصحَّح] 1.175rem = 18.8px — شبه بيضاوي على الأزرار، لغة استهلاكية.
     0.5rem = 8px يناسب سياق الاستشارات القانونية.
     هذا قرار جمالي — غيّره لو خالفتني الرأي. */
  --radius: 0.5rem;

  --shadow-x: 0px;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: hsl(0 0% 0%);
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.25);

  --tracking-normal: 0em;
  --spacing: 0.25rem;
}

.dark {
  --background: oklch(0.2598 0.0306 262.6666);
  --foreground: oklch(0.9219 0 0);
  --card: oklch(0.3106 0.0301 268.6365);
  --card-foreground: oklch(0.9219 0 0);
  --popover: oklch(0.2900 0.0249 268.3986);
  --popover-foreground: oklch(0.9219 0 0);

  /* [مُصحَّح] رُفعت الإضاءة في الداكن — الذهبي الغامق يذوب في خلفية داكنة.
     هذا هو الأصل في الوضع الداكن: الألوان تفتح لا تغمق. */
  --primary: oklch(0.7300 0.0904 80.9413);
  --primary-foreground: oklch(0.2100 0.0250 262.0000);

  /* [مُصحَّح] كان #D9D9D9 رمادياً فاتحاً — مستطيل ساطع وسط شاشة داكنة.
     صار سطحاً داكناً كما يجب. */
  --secondary: oklch(0.3550 0.0280 265.0000);
  --secondary-foreground: oklch(0.9219 0 0);

  --muted: oklch(0.3095 0.0266 266.7132);
  --muted-foreground: oklch(0.7155 0 0);
  --accent: oklch(0.3380 0.0589 267.5867);

  /* [مُصحَّح] 0.6325 -> 0.7050 — كان 3.41، صار 4.52 */
  --accent-foreground: oklch(0.7050 0.0904 80.9413);

  /* [مُصحَّح] رُفعت الإضاءة ليظهر الأحمر على خلفية داكنة */
  --destructive: oklch(0.7000 0.1900 25.3313);
  --destructive-foreground: oklch(0.2100 0.0250 262.0000);

  /* [جديد] ألوان الحالة في الوضع الداكن */
  --success: oklch(0.7200 0.1300 155.0000);
  --success-foreground: oklch(0.2100 0.0250 262.0000);
  --warning: oklch(0.7800 0.1300 75.0000);
  --warning-foreground: oklch(0.2100 0.0250 262.0000);
  --info: oklch(0.7300 0.1100 240.0000);
  --info-foreground: oklch(0.2100 0.0250 262.0000);

  --border: oklch(0.3843 0.0301 269.7337);
  --input: oklch(0.3843 0.0301 269.7337);
  --ring: oklch(0.7300 0.0904 80.9413);

  --chart-1: oklch(0.7300 0.0904 80.9413);
  --chart-2: oklch(0.7300 0.1100 240.0000);
  --chart-3: oklch(0.7200 0.1300 155.0000);
  --chart-4: oklch(0.5016 0.0849 259.4902);
  --chart-5: oklch(0.4241 0.0952 264.0306);

  --sidebar: oklch(0.3100 0.0283 267.7408);
  --sidebar-foreground: oklch(0.9219 0 0);

  /* [مُصحَّح] وُحّد على الذهبي — كان برتقالياً هنا أيضاً */
  --sidebar-primary: oklch(0.7300 0.0904 80.9413);
  --sidebar-primary-foreground: oklch(0.2100 0.0250 262.0000);

  --sidebar-accent: oklch(0.3380 0.0589 267.5867);
  --sidebar-accent-foreground: oklch(0.9219 0 0);
  --sidebar-border: oklch(0.3843 0.0301 269.7337);
  --sidebar-ring: oklch(0.7300 0.0904 80.9413);

  --font-sans: IBM Plex Sans Arabic, ui-sans-serif, sans-serif, system-ui;
  --font-serif: IBM Plex Serif, ui-serif, serif;
  --font-mono: IBM Plex Mono, ui-monospace, monospace;
  --radius: 0.5rem;

  --shadow-x: 0px;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: hsl(0 0% 0%);
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.25);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* [جديد] */
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);

  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
  --font-serif: var(--font-serif);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow: var(--shadow);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    /* [جديد] ارتفاع سطر أطول — العربية تحتاج مساحة رأسية
       للصعود والنزول والتشكيل أكثر من اللاتينية */
    line-height: 1.8;
  }
}
